export{ModalModeloCtrl};function ModalModeloCtrl($scope,$uibModalInstance,marcaSvc,modeloSvc,tS,params){$scope.tipoRegistro=1,$scope.data={},$scope.modelo={},$scope.marca={},$scope.getAllMarca=function(){try{marcaSvc.listForSelect({}).then(response=>{$scope.marcas=response}).catch(error=>{console.log(error)})}catch(error){console.log(error)}},$scope.getAllMarca(),"object"==typeof params&&params.idModelo>0&&($scope.tipoRegistro=2,$scope.data=Object.assign({},params),$scope.showStatus=!params.estado),$scope.resultModalMarca=function(result){$scope.getAllMarca()},$scope.saveAndUpdate=function(){try{const tituloToastr=1===$scope.tipoRegistro?"Guardar":"Actualizar";if(["",null,void 0].includes($scope.data.descripcion))return void tS.toastr("warning","Ingrese la descripciòn",tituloToastr);$scope.data.idModelo>0?modeloSvc.update($scope.data.idModelo,$scope.data).then($scope.successReponse).catch(err=>{hideLoader(),console.log(err)}):modeloSvc.save($scope.data).then($scope.successReponse).catch(err=>{hideLoader(),console.log(err)})}catch(error){hideLoader(),console.log(error)}},$scope.successReponse=function(response){hideLoader(),"0"===response.code&&tS.toastr("warning",response.message,response.titleSms),"1"===response.code&&(tS.toastr("success",response.message,response.titleSms),$uibModalInstance.close(response))},$scope.closeModal=function(){$uibModalInstance.close()}}ModalModeloCtrl.$inject=["$scope","$uibModalInstance","marcaService","modeloService","toastService","params"];